const WINDOWS_1252_BYTE_BY_CODE_POINT = new Map<number, number>([
  [0x20ac, 0x80],
  [0x201a, 0x82],
  [0x0192, 0x83],
  [0x201e, 0x84],
  [0x2026, 0x85],
  [0x2020, 0x86],
  [0x2021, 0x87],
  [0x02c6, 0x88],
  [0x2030, 0x89],
  [0x0160, 0x8a],
  [0x2039, 0x8b],
  [0x0152, 0x8c],
  [0x017d, 0x8e],
  [0x2018, 0x91],
  [0x2019, 0x92],
  [0x201c, 0x93],
  [0x201d, 0x94],
  [0x2022, 0x95],
  [0x2013, 0x96],
  [0x2014, 0x97],
  [0x02dc, 0x98],
  [0x2122, 0x99],
  [0x0161, 0x9a],
  [0x203a, 0x9b],
  [0x0153, 0x9c],
  [0x017e, 0x9e],
  [0x0178, 0x9f],
]);

function windows1252Bytes(value: string): Uint8Array | null {
  const bytes: number[] = [];
  for (const character of value) {
    const codePoint = character.codePointAt(0);
    if (codePoint === undefined) return null;

    if (codePoint <= 0xff) {
      bytes.push(codePoint);
      continue;
    }

    const mapped = WINDOWS_1252_BYTE_BY_CODE_POINT.get(codePoint);
    if (mapped === undefined) return null;
    bytes.push(mapped);
  }
  return new Uint8Array(bytes);
}

// Repara textos UTF-8 que foram decodificados indevidamente como Windows-1252.
// A conversão só é aceita quando o resultado é UTF-8 válido, sem caractere de
// substituição, evitando alterar textos Unicode que já estejam corretos.
export function fixUtf8Encoding(value: string): string {
  if (!/[ÃÂ]/.test(value)) return value;

  try {
    const bytes = windows1252Bytes(value);
    if (!bytes) return value;

    const decoded = new TextDecoder("utf-8", { fatal: true }).decode(bytes);
    return decoded.includes("\uFFFD") ? value : decoded;
  } catch {
    return value;
  }
}

export function validateAndNormalizeProducts(raw: any): ExtractedPayload {
  if (!raw || typeof raw !== 'object') {
    throw new Error("Payload retornado não é um objeto válido.");
  }

  const productsRaw = raw.products;
  if (!Array.isArray(productsRaw)) {
    throw new Error("A propriedade 'products' deve ser uma lista.");
  }

  const normalizedProducts: ExtractedProduct[] = [];
  const warnings: string[] = Array.isArray(raw.warnings) ? raw.warnings.map((w: any) => fixUtf8Encoding(String(w))) : [];

  for (let i = 0; i < productsRaw.length; i++) {
    const p = productsRaw[i];
    if (!p || typeof p !== 'object') continue;

    // Check required fields
    if (typeof p.name !== 'string' || !p.name.trim()) {
      continue; // Skip products without a valid name
    }

    let confidence = Number(p.confidence);
    if (isNaN(confidence) || confidence < 0 || confidence > 1) {
      confidence = 0.5; // fallback default
    }

    // Clean and validate cost
    let cost: number | null = null;
    if (p.cost !== undefined && p.cost !== null) {
      if (typeof p.cost === 'number') {
        if (p.cost >= 0) cost = p.cost;
      } else {
        let str = String(p.cost).trim();
        str = str.replace(/R\$\s?/gi, ''); // remove currency symbol
        // clean up thousands/decimals formatting
        if (str.includes(',') && !str.includes('.')) {
          str = str.replace(',', '.');
        } else if (str.includes(',') && str.includes('.')) {
          if (str.indexOf('.') < str.indexOf(',')) {
            str = str.replace(/\./g, '').replace(',', '.');
          } else {
            str = str.replace(/,/g, '');
          }
        }
        const val = parseFloat(str);
        if (!isNaN(val) && val >= 0) {
          cost = val;
        }
      }
    }

    // Clean page
    let page: number | null = null;
    if (p.page !== undefined && p.page !== null) {
      const val = parseInt(p.page, 10);
      if (!isNaN(val) && val >= 1) {
        page = val;
      }
    }

    // Clean string values, sanitize HTML/script tags if present
    const cleanString = (val: any): string | null => {
      if (val === undefined || val === null) return null;
      let str = String(val).trim();
      str = str.replace(/<[^>]*>/g, ''); // Simple script/HTML stripping
      return fixUtf8Encoding(str);
    };

    // Clean barcode
    let barcode = cleanString(p.barcode || p.ean);
    if (barcode) {
      // Basic EAN validation helper
      barcode = barcode.replace(/[^0-9]/g, '');
      if (barcode.length < 8 || barcode.length > 14) {
        barcode = null; // invalid barcode size
      }
    }

    normalizedProducts.push({
      name: fixUtf8Encoding(p.name.trim()).substring(0, 150),
      description: cleanString(p.description)?.substring(0, 500) || null,
      cost: cost,
      currency: cleanString(p.currency)?.substring(0, 3) || "BRL",
      supplier: cleanString(p.supplier)?.substring(0, 100) || null,
      product_url: cleanString(p.product_url)?.substring(0, 500) || null,
      sku: cleanString(p.sku)?.substring(0, 50) || null,
      barcode: barcode,
      page: page,
      confidence: confidence,
      evidence: cleanString(p.evidence)?.substring(0, 500) || null
    });
  }

  // Cap products at 500 to protect application performance
  const cappedProducts = normalizedProducts.slice(0, 500);

  return {
    products: cappedProducts,
    warnings
  };
}

﻿/**
 * r2.ts — Módulo compartilhado para acesso ao Cloudflare R2 via API S3
 * Usado pelas Edge Functions do Supabase para upload/download/delete de arquivos.
 *
 * Requer as variáveis de ambiente (Supabase Secrets):
 *   R2_ACCOUNT_ID   — ID da conta Cloudflare
 *   R2_ACCESS_KEY_ID — Access Key ID do R2 API Token
 *   R2_SECRET_ACCESS_KEY — Secret Access Key do R2 API Token
 *   R2_BUCKET_NAME  — Nome do bucket (gsa-hub-storage)
 *   R2_PUBLIC_URL   — URL pública do bucket R2
 */

export const R2_BUCKET = Deno.env.get('R2_BUCKET_NAME') ?? 'gsa-hub-storage';
export const R2_PUBLIC_URL = Deno.env.get('R2_PUBLIC_URL') ?? 'https://pub-7f7b1419c83c407ba9bcf6512329e79a.r2.dev';

const R2_ACCOUNT_ID = () => Deno.env.get('R2_ACCOUNT_ID') ?? '';
const R2_ACCESS_KEY = () => Deno.env.get('R2_ACCESS_KEY_ID') ?? '';
const R2_SECRET_KEY = () => Deno.env.get('R2_SECRET_ACCESS_KEY') ?? '';

function getEndpoint() {
  return `https://${R2_ACCOUNT_ID()}.r2.cloudflarestorage.com`;
}

// ─── AWS Signature V4 ─────────────────────────────────────────────────────────
async function hmac(key: ArrayBuffer | Uint8Array, data: string): Promise<ArrayBuffer> {
  const k = await crypto.subtle.importKey('raw', key, { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  return crypto.subtle.sign('HMAC', k, new TextEncoder().encode(data));
}

async function sha256hex(data: string | Uint8Array): Promise<string> {
  const buf = typeof data === 'string' ? new TextEncoder().encode(data) : data;
  const hash = await crypto.subtle.digest('SHA-256', buf);
  return Array.from(new Uint8Array(hash)).map(b => b.toString(16).padStart(2, '0')).join('');
}

async function signRequest(
  method: string,
  key: string,
  body: Uint8Array | null,
  contentType?: string,
): Promise<Record<string, string>> {
  const endpoint = getEndpoint();
  const region = 'auto';
  const service = 's3';
  const now = new Date();
  const date = now.toISOString().slice(0, 10).replace(/-/g, '');
  const datetime = now.toISOString().replace(/[-:]/g, '').slice(0, 15) + 'Z';
  const host = new URL(endpoint).host;

  const payloadHash = body ? await sha256hex(body) : 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855';
  const signedHeaders = contentType
    ? 'content-type;host;x-amz-content-sha256;x-amz-date'
    : 'host;x-amz-content-sha256;x-amz-date';

  const canonicalHeaders = contentType
    ? `content-type:${contentType}\nhost:${host}\nx-amz-content-sha256:${payloadHash}\nx-amz-date:${datetime}\n`
    : `host:${host}\nx-amz-content-sha256:${payloadHash}\nx-amz-date:${datetime}\n`;

  const canonicalPath = `/${R2_BUCKET}/${key.replace(/^\/+/, '')}`;
  const canonicalRequest = [method, canonicalPath, '', canonicalHeaders, signedHeaders, payloadHash].join('\n');

  const credentialScope = `${date}/${region}/${service}/aws4_request`;
  const stringToSign = ['AWS4-HMAC-SHA256', datetime, credentialScope, await sha256hex(canonicalRequest)].join('\n');

  const enc = new TextEncoder();
  const kDate = await hmac(enc.encode(`AWS4${R2_SECRET_KEY()}`), date);
  const kRegion = await hmac(kDate, region);
  const kService = await hmac(kRegion, service);
  const kSigning = await hmac(kService, 'aws4_request');
  const signatureBytes = await hmac(kSigning, stringToSign);
  const signature = Array.from(new Uint8Array(signatureBytes)).map(b => b.toString(16).padStart(2, '0')).join('');

  const authHeader = `AWS4-HMAC-SHA256 Credential=${R2_ACCESS_KEY()}/${credentialScope}, SignedHeaders=${signedHeaders}, Signature=${signature}`;

  return {
    Authorization: authHeader,
    'x-amz-date': datetime,
    'x-amz-content-sha256': payloadHash,
    ...(contentType ? { 'Content-Type': contentType } : {}),
  };
}

// ─── Upload de arquivo ────────────────────────────────────────────────────────
export async function r2Upload(
  key: string,
  body: Uint8Array,
  contentType: string,
): Promise<{ publicUrl: string; path: string }> {
  const normalizedKey = key.replace(/^\/+/, '');
  const headers = await signRequest('PUT', normalizedKey, body, contentType);

  const resp = await fetch(`${getEndpoint()}/${R2_BUCKET}/${normalizedKey}`, {
    method: 'PUT',
    headers,
    body,
  });

  if (!resp.ok) {
    const text = await resp.text();
    throw new Error(`R2 upload falhou [${resp.status}]: ${text}`);
  }

  return {
    publicUrl: `${R2_PUBLIC_URL}/${normalizedKey}`,
    path: normalizedKey,
  };
}

// ─── Download de arquivo ──────────────────────────────────────────────────────
export async function r2Download(key: string): Promise<{ body: Uint8Array; contentType: string }> {
  const normalizedKey = key.replace(/^\/+/, '');
  const headers = await signRequest('GET', normalizedKey, null);

  const resp = await fetch(`${getEndpoint()}/${R2_BUCKET}/${normalizedKey}`, { headers });
  if (!resp.ok) throw new Error(`R2 download falhou [${resp.status}]`);

  const body = new Uint8Array(await resp.arrayBuffer());
  const contentType = resp.headers.get('content-type') ?? 'application/octet-stream';
  return { body, contentType };
}

// ─── Delete de arquivo(s) ────────────────────────────────────────────────────
export async function r2Delete(keys: string[]): Promise<void> {
  await Promise.all(
    keys.map(async (key) => {
      const normalizedKey = key.replace(/^\/+/, '');
      const headers = await signRequest('DELETE', normalizedKey, null);
      const resp = await fetch(`${getEndpoint()}/${R2_BUCKET}/${normalizedKey}`, { method: 'DELETE', headers });
      if (!resp.ok && resp.status !== 404) {
        throw new Error(`R2 delete falhou [${resp.status}]: ${key}`);
      }
    }),
  );
}

// ─── URL pública ──────────────────────────────────────────────────────────────
export function r2PublicUrl(key: string): string {
  return `${R2_PUBLIC_URL}/${key.replace(/^\/+/, '')}`;
}

